//! Generator for Claudine's shipped artifact,
//! `claudine/lib/generated/shipped.json`: the prepared trigger bundle and
//! host catalog the library loads instead of preparing their YAML text.
//!
//! - no flag: accepts freshly generated bytes as an artifact over the fresh
//!   Simplified Schema and Darkmatter artifacts of the same generation, then
//!   prints them to stdout (the root `just shipped-schemas` coordinator reads
//!   this); each `--lower <owner>=<path>` (`simplified-schema` or
//!   `darkmatter`) also requires the file at `<path>` to equal that fresh
//!   lower artifact. A refusal exits 1 and prints nothing. The compiled-in
//!   lower artifacts are not consulted.
//! - `--check`: fails when the checked-in artifact (or `--artifact <path>`)
//!   is refused or differs from fresh generation
//! - `--write`: replaces the checked-in artifact with fresh generation
//!
//! `--check` and `--write` first require both compiled-in lower artifacts
//! (Simplified Schema's and Darkmatter's) to equal their fresh generation,
//! and otherwise name the root `just shipped-schemas`, which regenerates all
//! three in order. Generation reads only the compiled-in text, never a
//! checked-in artifact, so it runs even when any artifact is malformed or
//! stale. Errors go to stderr; stdout carries only artifact bytes. The
//! library's L1 suite compiles this file as a module and drives [`run`]
//! in-process.
//!
//! ```text
//! cargo run -p claudine --example shipped_schemas -- --check
//! ```

use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use claudine::composition::schema::shipped::{self as artifact, FreshClaudine};
use darkmatter::markdown::schemas::shipped::{self as darkmatter_artifact, FreshDarkmatter};
use simplified_schema::shipped::{self as mechanism, DependencyFingerprint, FreshLower, LowerArtifact, registry as lower};

#[allow(dead_code)]
fn main() -> ExitCode {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("generated/shipped.json");
    let code = run(
        std::env::args().skip(1),
        &path,
        CompiledLowers { lower: lower::ARTIFACT, darkmatter: darkmatter_artifact::ARTIFACT },
        generate,
        &mut std::io::stdout().lock(),
        &mut std::io::stderr().lock(),
    );
    ExitCode::from(code)
}

/// The lower artifacts this build embeds.
#[derive(Clone, Copy)]
pub struct CompiledLowers<'a> {
    pub lower: &'a [u8],
    pub darkmatter: &'a [u8],
}

/// One generation: the fresh Simplified Schema and Darkmatter artifacts and
/// Claudine's artifact prepared over them.
pub struct Generated {
    pub lower: Vec<u8>,
    pub darkmatter: Vec<u8>,
    pub artifact: Vec<u8>,
}

/// Generates all three artifacts from current text, uncached.
pub fn generate() -> Result<Generated, String> {
    let fresh_lower = FreshLower::prepare()?;
    let fresh_darkmatter = FreshDarkmatter::prepare(&fresh_lower)?;
    let fresh = FreshClaudine::prepare(&fresh_lower, &fresh_darkmatter)?;
    Ok(Generated {
        lower: fresh_lower.artifact().to_vec(),
        darkmatter: fresh_darkmatter.artifact().to_vec(),
        artifact: fresh.artifact().to_vec(),
    })
}

enum Mode {
    Emit,
    Check,
    Write,
}

const USAGE: &str = "usage: shipped_schemas [--lower <owner>=<path>]... | shipped_schemas (--check [--artifact <path>] | --write)";

/// The lower artifacts' owners, in dependency order.
const LOWER_OWNERS: [&str; 2] = [lower::OWNER, darkmatter_artifact::OWNER];

struct Arguments {
    mode: Mode,
    /// `--artifact`: the file `--check` reads instead of the checked-in one.
    supplied: Option<PathBuf>,
    /// `--lower <owner>=<path>`, indexed like [`LOWER_OWNERS`]: the lower
    /// candidates emitted bytes must be built over.
    lower_candidates: [Option<PathBuf>; 2],
}

/// Runs the generator over `arguments`: `0` on success, `1` on a refused,
/// stale, or failed generation, `2` on a usage error. `path` is the
/// checked-in file `--check` reads by default and `--write` replaces.
pub fn run(
    arguments: impl IntoIterator<Item = String>,
    path: &Path,
    compiled_lowers: CompiledLowers<'_>,
    generate: impl FnOnce() -> Result<Generated, String>,
    stdout: &mut dyn Write,
    stderr: &mut dyn Write,
) -> u8 {
    let Arguments { mode, supplied, lower_candidates } = match parse_arguments(arguments.into_iter()) {
        Ok(parsed) => parsed,
        Err(message) => {
            let _ = writeln!(stderr, "error: {message}\n{USAGE}");
            return 2;
        }
    };
    let generated = match generate() {
        Ok(generated) => generated,
        Err(message) => {
            let _ = writeln!(stderr, "error: generating `{}` failed: {message}", artifact::ARTIFACT_PATH);
            return 1;
        }
    };
    if !matches!(mode, Mode::Emit) {
        let stale = [
            (lower::ARTIFACT_PATH, generated.lower.as_slice(), compiled_lowers.lower),
            (darkmatter_artifact::ARTIFACT_PATH, generated.darkmatter.as_slice(), compiled_lowers.darkmatter),
        ];
        if let Some((stale_path, _, _)) = stale.iter().find(|(_, fresh, compiled)| fresh != compiled) {
            let _ = writeln!(
                stderr,
                "error: the compiled-in `{stale_path}` is stale, so `{}` cannot be checked or written over it; regenerate every artifact with `{}` from the repository root",
                artifact::ARTIFACT_PATH,
                artifact::REGENERATE_COMMAND
            );
            return 1;
        }
    }
    match mode {
        Mode::Emit => {
            if let Err(message) = accept_candidate(&generated, &lower_candidates) {
                let _ = writeln!(stderr, "error: {message}");
                return 1;
            }
            match stdout.write_all(&generated.artifact).and_then(|()| stdout.flush()) {
                Ok(()) => 0,
                Err(error) => {
                    let _ = writeln!(stderr, "error: cannot write to stdout: {error}");
                    1
                }
            }
        }
        Mode::Check => check(supplied.as_deref().unwrap_or(path), &generated.artifact, stderr),
        Mode::Write => write(path, &generated.artifact, stderr),
    }
}

fn parse_arguments(arguments: impl Iterator<Item = String>) -> Result<Arguments, String> {
    let mut mode = Mode::Emit;
    let mut supplied = None;
    let mut lower_candidates: [Option<PathBuf>; 2] = [None, None];
    let mut arguments = arguments;
    while let Some(argument) = arguments.next() {
        match argument.as_str() {
            "--check" | "--write" if !matches!(mode, Mode::Emit) => {
                return Err("`--check` and `--write` are mutually exclusive".into());
            }
            "--check" => mode = Mode::Check,
            "--write" => mode = Mode::Write,
            "--artifact" => supplied = Some(PathBuf::from(arguments.next().ok_or("`--artifact` needs a path")?)),
            "--lower" => {
                let value = arguments.next().ok_or("`--lower` needs `<owner>=<path>`")?;
                let slot = value
                    .split_once('=')
                    .filter(|(_, path)| !path.is_empty())
                    .and_then(|(owner, path)| Some((LOWER_OWNERS.iter().position(|lower| *lower == owner)?, owner, path)));
                let Some((index, owner, path)) = slot else {
                    return Err(format!("`--lower` takes `<owner>=<path>` naming one of {LOWER_OWNERS:?}, not `{value}`"));
                };
                if lower_candidates[index].replace(PathBuf::from(path)).is_some() {
                    return Err(format!("`--lower {owner}=…` is given twice"));
                }
            }
            other => return Err(format!("unexpected argument `{other}`")),
        }
    }
    if supplied.is_some() && !matches!(mode, Mode::Check) {
        return Err("`--artifact` applies only to `--check`".into());
    }
    if lower_candidates.iter().any(Option::is_some) && !matches!(mode, Mode::Emit) {
        return Err("`--lower` applies only when emitting".into());
    }
    Ok(Arguments { mode, supplied, lower_candidates })
}

/// Accepts the generated artifact over the fresh lower artifacts it was
/// prepared over, after requiring each supplied lower candidate (the lower
/// bytes a caller will publish beside it) to be that same lower artifact.
fn accept_candidate(generated: &Generated, lower_candidates: &[Option<PathBuf>; 2]) -> Result<(), String> {
    let fresh_lowers = [generated.lower.as_slice(), generated.darkmatter.as_slice()];
    for ((owner, fresh), candidate) in LOWER_OWNERS.iter().zip(fresh_lowers).zip(lower_candidates) {
        let Some(path) = candidate else { continue };
        let bytes = std::fs::read(path).map_err(|error| format!("cannot read `{}`: {error}", path.display()))?;
        if bytes != fresh {
            return Err(format!(
                "`{}` is not the `{owner}` artifact this generation of `{}` is built over",
                path.display(),
                artifact::ARTIFACT_PATH
            ));
        }
    }
    let lowers = [
        LowerArtifact::Current(DependencyFingerprint::of_bytes(lower::OWNER, lower::PREPARATION_REVISION, &generated.lower)),
        LowerArtifact::Current(DependencyFingerprint::of_bytes(
            darkmatter_artifact::OWNER,
            darkmatter_artifact::PREPARATION_REVISION,
            &generated.darkmatter,
        )),
    ];
    artifact::Registry::load_over(Some(&generated.artifact), lowers)
        .check_all()
        .map_err(|refusal| format!("freshly generated `{}` is refused: {refusal}", artifact::ARTIFACT_PATH))
}

fn check(path: &Path, fresh: &[u8], stderr: &mut dyn Write) -> u8 {
    let checked_in = match std::fs::read(path) {
        Ok(bytes) => bytes,
        Err(error) => {
            let _ = writeln!(stderr, "error: cannot read `{}`: {error}", path.display());
            return 1;
        }
    };
    if let Err(refusal) = artifact::check_artifact(&checked_in) {
        let _ = writeln!(
            stderr,
            "error: `{}` is refused: {refusal}\nregenerate it with `{}`",
            path.display(),
            artifact::REGENERATE_COMMAND
        );
        return 1;
    }
    match mechanism::check_fresh(&checked_in, fresh, artifact::ARTIFACT_PATH, artifact::REGENERATE_COMMAND) {
        Ok(()) => 0,
        Err(stale) => {
            let _ = writeln!(stderr, "error: {stale}");
            1
        }
    }
}

/// Validates `fresh` as an artifact before replacing `path` through a
/// sibling temporary file, so a failure leaves the old file in place.
fn write(path: &Path, fresh: &[u8], stderr: &mut dyn Write) -> u8 {
    if let Err(refusal) = artifact::check_artifact(fresh) {
        let _ = writeln!(stderr, "error: freshly generated bytes are refused: {refusal}");
        return 1;
    }
    if std::fs::read(path).is_ok_and(|current| current == fresh) {
        return 0;
    }
    let temporary = path.with_extension("json.tmp");
    if let Err(error) = std::fs::write(&temporary, fresh).and_then(|()| std::fs::rename(&temporary, path)) {
        let _ = std::fs::remove_file(&temporary);
        let _ = writeln!(stderr, "error: cannot write `{}`: {error}", path.display());
        return 1;
    }
    0
}
